      "java_class_methods": {
        "title": "Java Class Methods",
        "summary": "Membedakan `static` method (dapat dipanggil tanpa membuat objek) dan `public` method (wajib dipanggil via objek).",
        "content": "<p class=\"lead\">Membedakan `static` method (dapat dipanggil tanpa membuat objek) dan `public` method (wajib dipanggil via objek).</p>\n<div class=\"card bg-light border-0 p-3 mb-4 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-brands fa-java text-danger me-2\"></i>Konsep Kunci Java Class Methods:</h6>\n    <p class=\"small mb-0\" style=\"line-height: 1.8;\">\n        Pelajari arsitektur sintaks Java di bawah, perhatikan aturan kompilasi JVM yang ketat (Strongly-Typed), dan uji secara langsung di Code Lab Skillance Academy.\n    </p>\n</div>",
        "example_title": "Contoh Kode Java: Java Class Methods",
        "example_code": "// Skrip Java 21 - Skillance Academy Indonesia\nclass Aksi {\n    static void statis() { System.out.println(\"Method Static\"); }\n    void publik() { System.out.println(\"Method Public Instance\"); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Aksi.statis();\n        new Aksi().publik();\n    }\n}",
        "explanation": "<p>Uji skrip Java untuk topik <strong>Java Class Methods</strong> di atas dan amati hasil kompilasi terminal JVM secara instan.</p>"
      },
      "java_challenges_class": {
        "title": "Java Class Challenge",
        "summary": "Studi kasus merancang class entitas bisnis lengkap dengan atribut dan perilaku interaktif.",
        "content": "<p class=\"lead\">Studi kasus merancang class entitas bisnis lengkap dengan atribut dan perilaku interaktif.</p>\n<div class=\"card bg-light border-0 p-3 mb-4 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-brands fa-java text-danger me-2\"></i>Konsep Kunci Java Class Challenge:</h6>\n    <p class=\"small mb-0\" style=\"line-height: 1.8;\">\n        Pelajari arsitektur sintaks Java di bawah, perhatikan aturan kompilasi JVM yang ketat (Strongly-Typed), dan uji secara langsung di Code Lab Skillance Academy.\n    </p>\n</div>",
        "example_title": "Contoh Kode Java: Java Class Challenge",
        "example_code": "// Skrip Java 21 - Skillance Academy Indonesia\nclass Rekening {\n    int saldo = 500000;\n    void setor(int j) { saldo += j; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Rekening r = new Rekening();\n        r.setor(150000);\n        System.out.println(\"Saldo Akhir: Rp \" + r.saldo);\n    }\n}",
