      "java_try_catch": {
        "title": "Java Exceptions",
        "summary": "Menangani error perkecualian (Exception Handling) menggunakan blok `try`, `catch`, dan `finally`.",
        "content": "<p class=\"lead\">Menangani error perkecualian (Exception Handling) menggunakan blok `try`, `catch`, dan `finally`.</p>\n<div class=\"card bg-light border-0 p-3 mb-4 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-brands fa-java text-danger me-2\"></i>Konsep Kunci Java Exceptions:</h6>\n    <p class=\"small mb-0\" style=\"line-height: 1.8;\">\n        Pelajari arsitektur sintaks Java di bawah, perhatikan aturan kompilasi JVM yang ketat (Strongly-Typed), dan uji secara langsung di Code Lab Skillance Academy.\n    </p>\n</div>",
        "example_title": "Contoh Kode Java: Java Exceptions",
        "example_code": "// Skrip Java 21 - Skillance Academy Indonesia\npublic class Main {\n    public static void main(String[] args) {\n        try {\n            int[] arr = {1, 2};\n            System.out.println(arr[10]);\n        } catch (ArrayIndexOutOfBoundsException e) {\n            System.out.println(\"Tertangkap: Indeks array di luar batas!\");\n        } finally {\n            System.out.println(\"Blok finally selalu dijalankan.\");\n        }\n    }\n}",
        "explanation": "<p>Uji skrip Java untuk topik <strong>Java Exceptions</strong> di atas dan amati hasil kompilasi terminal JVM secara instan.</p>"
      },
      "java_exceptions_multiple": {
        "title": "Java Multiple Exceptions",
        "summary": "Menangkap beberapa jenis perkecualian sekaligus dalam satu blok penanganan multi-catch `catch (TypeA | TypeB e)`.",
        "content": "<p class=\"lead\">Menangkap beberapa jenis perkecualian sekaligus dalam satu blok penanganan multi-catch `catch (TypeA | TypeB e)`.</p>\n<div class=\"card bg-light border-0 p-3 mb-4 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-brands fa-java text-danger me-2\"></i>Konsep Kunci Java Multiple Exceptions:</h6>\n    <p class=\"small mb-0\" style=\"line-height: 1.8;\">\n        Pelajari arsitektur sintaks Java di bawah, perhatikan aturan kompilasi JVM yang ketat (Strongly-Typed), dan uji secara langsung di Code Lab Skillance Academy.\n    </p>\n</div>",
        "example_title": "Contoh Kode Java: Java Multiple Exceptions",
        "example_code": "// Skrip Java 21 - Skillance Academy Indonesia\npublic class Main {\n    public static void main(String[] args) {\n        try {\n            int x = 10 / 0;\n        } catch (ArithmeticException | NullPointerException e) {\n            System.out.println(\"Tertangkap Error: \" + e.getMessage());\n        }\n    }\n}",
